fn main() -> Int {
  var arr: [5]Int = mem.zeroed();
  arr[0] = 1;
  arr[1] = 2;
  arr[2] = 3;
  arr[3] = 4;
  arr[4] = 5;
  return arr[0] + arr[1] + arr[2] + arr[3] + arr[4];
